/* krsha256.c -- SHA-256 (FIPS 180-4) of files, for the OPENSTEP build host.
 * C89. Written for this project (no copied code). Constants generated by
 * Python from the fractional parts of prime square/cube roots.
 *
 * usage: krsha256 FILE...     prints "HEX SIZE PATH" per file.
 * Exit 0 only if every file was read completely; files over KR_MAXSIZE are
 * refused.  stdin is not supported.
 */
#include <stdio.h>
#include <string.h>

#ifndef KR_BUFSZ
#define KR_BUFSZ 8192
#endif
#define KR_MAXSIZE 268435456UL          /* 256 MiB */
#define M32(x) ((x) & 0xffffffffUL)
#define ROR(x, n) M32((M32(x) >> (n)) | (M32(x) << (32 - (n))))

typedef unsigned long u32;              /* at least 32 bits; masked everywhere */

static const u32 K[64] = {
    0x428a2f98UL, 0x71374491UL, 0xb5c0fbcfUL, 0xe9b5dba5UL,
    0x3956c25bUL, 0x59f111f1UL, 0x923f82a4UL, 0xab1c5ed5UL,
    0xd807aa98UL, 0x12835b01UL, 0x243185beUL, 0x550c7dc3UL,
    0x72be5d74UL, 0x80deb1feUL, 0x9bdc06a7UL, 0xc19bf174UL,
    0xe49b69c1UL, 0xefbe4786UL, 0x0fc19dc6UL, 0x240ca1ccUL,
    0x2de92c6fUL, 0x4a7484aaUL, 0x5cb0a9dcUL, 0x76f988daUL,
    0x983e5152UL, 0xa831c66dUL, 0xb00327c8UL, 0xbf597fc7UL,
    0xc6e00bf3UL, 0xd5a79147UL, 0x06ca6351UL, 0x14292967UL,
    0x27b70a85UL, 0x2e1b2138UL, 0x4d2c6dfcUL, 0x53380d13UL,
    0x650a7354UL, 0x766a0abbUL, 0x81c2c92eUL, 0x92722c85UL,
    0xa2bfe8a1UL, 0xa81a664bUL, 0xc24b8b70UL, 0xc76c51a3UL,
    0xd192e819UL, 0xd6990624UL, 0xf40e3585UL, 0x106aa070UL,
    0x19a4c116UL, 0x1e376c08UL, 0x2748774cUL, 0x34b0bcb5UL,
    0x391c0cb3UL, 0x4ed8aa4aUL, 0x5b9cca4fUL, 0x682e6ff3UL,
    0x748f82eeUL, 0x78a5636fUL, 0x84c87814UL, 0x8cc70208UL,
    0x90befffaUL, 0xa4506cebUL, 0xbef9a3f7UL, 0xc67178f2UL
};

static const u32 H0[8] = {
    0x6a09e667UL, 0xbb67ae85UL, 0x3c6ef372UL, 0xa54ff53aUL,
    0x510e527fUL, 0x9b05688cUL, 0x1f83d9abUL, 0x5be0cd19UL
};

struct sha {
    u32 h[8];
    unsigned char blk[64];
    unsigned int n;                     /* bytes in blk */
    u32 len_lo, len_hi;                 /* message length in bytes, 64-bit */
};

static void sha_init(struct sha *s)
{
    int i;
    for (i = 0; i < 8; i++)
        s->h[i] = H0[i];
    s->n = 0;
    s->len_lo = s->len_hi = 0;
}

static void sha_block(struct sha *s, const unsigned char *p)
{
    u32 w[64], a, b, c, d, e, f, g, h, t1, t2;
    int i;

    for (i = 0; i < 16; i++)
        w[i] = ((u32)p[4 * i] << 24) | ((u32)p[4 * i + 1] << 16) |
               ((u32)p[4 * i + 2] << 8) | (u32)p[4 * i + 3];
    for (i = 16; i < 64; i++) {
        u32 s0 = ROR(w[i - 15], 7) ^ ROR(w[i - 15], 18) ^ (M32(w[i - 15]) >> 3);
        u32 s1 = ROR(w[i - 2], 17) ^ ROR(w[i - 2], 19) ^ (M32(w[i - 2]) >> 10);
        w[i] = M32(w[i - 16] + s0 + w[i - 7] + s1);
    }
    a = s->h[0]; b = s->h[1]; c = s->h[2]; d = s->h[3];
    e = s->h[4]; f = s->h[5]; g = s->h[6]; h = s->h[7];
    for (i = 0; i < 64; i++) {
        t1 = M32(h + (ROR(e, 6) ^ ROR(e, 11) ^ ROR(e, 25)) +
                 ((e & f) ^ (M32(~e) & g)) + K[i] + w[i]);
        t2 = M32((ROR(a, 2) ^ ROR(a, 13) ^ ROR(a, 22)) +
                 ((a & b) ^ (a & c) ^ (b & c)));
        h = g; g = f; f = e; e = M32(d + t1);
        d = c; c = b; b = a; a = M32(t1 + t2);
    }
    s->h[0] = M32(s->h[0] + a); s->h[1] = M32(s->h[1] + b);
    s->h[2] = M32(s->h[2] + c); s->h[3] = M32(s->h[3] + d);
    s->h[4] = M32(s->h[4] + e); s->h[5] = M32(s->h[5] + f);
    s->h[6] = M32(s->h[6] + g); s->h[7] = M32(s->h[7] + h);
}

static void sha_update(struct sha *s, const unsigned char *p, unsigned long len)
{
    u32 old = s->len_lo;
    s->len_lo = M32(s->len_lo + len);
    if (s->len_lo < old)
        s->len_hi = M32(s->len_hi + 1);
    while (len > 0) {
        unsigned int take = 64 - s->n;
        if ((unsigned long)take > len)
            take = (unsigned int)len;
        memcpy(s->blk + s->n, p, take);
        s->n += take; p += take; len -= take;
        if (s->n == 64) {
            sha_block(s, s->blk);
            s->n = 0;
        }
    }
}

static void sha_final(struct sha *s, unsigned char out[32])
{
    u32 bits_hi = M32((s->len_hi << 3) | (s->len_lo >> 29));
    u32 bits_lo = M32(s->len_lo << 3);
    unsigned char pad[64];
    unsigned char lenb[8];
    unsigned int padlen;
    int i;

    memset(pad, 0, sizeof pad);
    pad[0] = 0x80;
    padlen = (s->n < 56) ? 56 - s->n : 120 - s->n;
    for (i = 0; i < 4; i++) {
        lenb[i] = (unsigned char)(bits_hi >> (24 - 8 * i));
        lenb[4 + i] = (unsigned char)(bits_lo >> (24 - 8 * i));
    }
    {
        u32 lo = s->len_lo, hi = s->len_hi;     /* padding must not count */
        sha_update(s, pad, padlen);
        sha_update(s, lenb, 8);
        s->len_lo = lo; s->len_hi = hi;
    }
    for (i = 0; i < 8; i++) {
        out[4 * i] = (unsigned char)(s->h[i] >> 24);
        out[4 * i + 1] = (unsigned char)(s->h[i] >> 16);
        out[4 * i + 2] = (unsigned char)(s->h[i] >> 8);
        out[4 * i + 3] = (unsigned char)s->h[i];
    }
}

static unsigned char buf[KR_BUFSZ];

int main(int argc, char **argv)
{
    int i, j, rc = 0;

    if (argc < 2) {
        fprintf(stderr, "usage: krsha256 FILE...\n");
        return 2;
    }
    if (sizeof(u32) < 4) {
        fprintf(stderr, "krsha256: unsigned long is narrower than 32 bits\n");
        return 2;
    }
    for (i = 1; i < argc; i++) {
        FILE *f = fopen(argv[i], "rb");
        struct sha s;
        unsigned long total = 0;
        unsigned char dg[32];
        size_t got;
        int bad = 0;

        if (f == NULL) {
            fprintf(stderr, "krsha256: cannot open %s\n", argv[i]);
            rc = 1;
            continue;
        }
        sha_init(&s);
        for (;;) {
            got = fread(buf, 1, sizeof buf, f);
            if (got > 0) {
                if (total + got > KR_MAXSIZE || total + got < total) {
                    fprintf(stderr, "krsha256: %s larger than %lu bytes\n",
                            argv[i], KR_MAXSIZE);
                    bad = 1;
                    break;
                }
                total += got;
                sha_update(&s, buf, (unsigned long)got);
            }
            if (got < sizeof buf) {
                if (ferror(f)) {
                    fprintf(stderr, "krsha256: read error on %s\n", argv[i]);
                    bad = 1;
                    break;
                }
                if (feof(f))
                    break;
            }
        }
        if (fclose(f) != 0 && !bad) {
            fprintf(stderr, "krsha256: close error on %s\n", argv[i]);
            bad = 1;
        }
        if (bad) {
            rc = 1;
            continue;
        }
        sha_final(&s, dg);
        for (j = 0; j < 32; j++)
            printf("%02x", dg[j]);
        printf(" %lu %s\n", total, argv[i]);
    }
    if (fflush(stdout) != 0)
        rc = 1;
    return rc;
}
